#include "edudb.hpp"
#include <algorithm>
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <map>
#include <cstdlib>
using namespace edudb;
namespace fs=std::filesystem;
namespace {
std::size_t checks=0;
void require(bool b,const char* m){++checks;if(!b)throw std::runtime_error(m);}
template<class F>void rejects(F fn,const std::string& code){bool caught=false;try{fn();}catch(const DbError& e){caught=e.code==code;}require(caught,"Expected precise Storage error");}
json column(const char* name,const char* type,std::size_t length=0){return {{"name",name},{"type",type},{"length",length},{"not_null",false},{"primary",false},{"unique",false},{"default",nullptr}};}
json definition(const char* format="VARIABLE"){
    return {{"record_format",format},{"columns",json::array({column("id","INTEGER"),column("dept","INTEGER"),column("name","VARCHAR",32),column("payload","BLOB",16777216)})},{"rows",json::array()},
        {"indexes",json::array({{{"name","ix_id"},{"column","id"},{"columns",json::array({"id"})},{"method","BPLUS"},{"unique",true},{"options",{{"max_keys",7}}}},{{"name","ix_dept"},{"column","dept"},{"columns",json::array({"dept"})},{"method","BPLUS"},{"unique",false},{"options",{{"max_keys",7}}}}})}};
}
std::vector<StoredRow> rows(Storage& db,const std::shared_ptr<Transaction>& tx,const std::string& name){auto cursor=db.scan(tx,name);std::vector<StoredRow> out;StoredRow row;while(cursor->next(row))out.push_back(row);return out;}
StoredRow by_id(Storage& db,const std::shared_ptr<Transaction>& tx,const std::string& name,int id){auto all=rows(db,tx,name);for(const auto& row:all)if(row.values[0]==id)return row;throw std::runtime_error("Missing fixture row");}
std::map<int,json> values(Storage& db,const std::shared_ptr<Transaction>& tx,const std::string& name){std::map<int,json> out;for(const auto& row:rows(db,tx,name))require(out.emplace(row.values[0].get<int>(),row.values).second,"Unique fixture id");return out;}
void verify(Storage& db,const std::shared_ptr<Transaction>& tx){auto check=db.verify(tx);if(!check.value("ok",false))throw std::runtime_error("verify: "+check.dump());++checks;}
void initialize(Storage& db){auto tx=db.begin();db.create_cluster(tx,"教学聚簇");auto a=definition("FIXED"),b=definition();for(int i=0;i<12;++i){a["rows"].push_back(json::array({i,i%3,"学生"+std::to_string(i),nullptr}));b["rows"].push_back(json::array({i,i%3,"课程"+std::to_string(i),nullptr}));}a["rows"][0][3]={{"$blob",std::string(32768,'A')}};db.write_table(tx,"a",a);db.write_table(tx,"b",b);db.attach_cluster(tx,"教学聚簇","a",{"dept"});db.attach_cluster(tx,"教学聚簇","b",{"dept"});
    auto catalog=db.catalog(tx);require(catalog.size()==2&&catalog.contains("a")&&catalog.contains("b")&&!catalog.contains("教学聚簇"),"Public catalog remains flat tables only");auto ca=db.cluster_lock_resource(tx,"a"),cb=db.cluster_lock_resource(tx,"b");require(!ca.empty()&&ca==cb,"Both member tables expose same cluster lock resource");
    auto shape=db.inspect_cluster(tx,"教学聚簇",2048);bool shared=false;for(const auto& p:shape["pages"])shared|=p["table_row_counts"].size()==2;require(shared,"Actual selected shared HEAP page contains both tableOID tags");auto metadata=db.read_table(tx,"a",false);require(metadata["physical_stats"]["table_pages"]>0&&metadata["heap_pages_shared"]==true,"Cluster table scan physical pages are not empty standalone heap vector");require(metadata["physical_stats"]["organization"]["shared_cluster_rows"]==24&&metadata["physical_stats"]["organization"]["target_table_rows"]==12&&metadata["physical_stats"]["organization"]["other_table_rows"]==12,"Shared pages and own/other row counts are distinguished");require(metadata["record_layout"]["fixed_record_bytes"].get<std::size_t>()==metadata["record_layout"]["member_codec_bytes"].get<std::size_t>()+8,"Cluster fixed slot layout includes actual tableOID prefix");verify(db,tx);db.commit(tx);
}
void lifecycle(const fs::path& path){std::map<int,json> model_a,model_b;
    {Storage db(path.u8string(),3);initialize(db);auto tx=db.begin();model_a=values(db,tx,"a");model_b=values(db,tx,"b");auto extra=definition();db.write_table(tx,"normal",extra);require(db.clusters(tx).contains("教学聚簇"),"Ordinary CREATE preserves extended cluster catalog");db.drop_table(tx,"normal");require(db.clusters(tx).contains("教学聚簇"),"Ordinary DROP preserves extended cluster catalog");db.commit(tx);db.checkpoint();}
    {Storage db(path.u8string(),3);auto tx=db.begin();require(values(db,tx,"a")==model_a&&values(db,tx,"b")==model_b,"Cluster values/indexes reopen");require(db.index_scan(tx,"a","ix_id","=",5).at(0)==model_a.at(5),"Secondary B+ index gets clustered row through member map");
        auto first=by_id(db,tx,"a",0),other=by_id(db,tx,"b",0);auto changed=first.values;changed[1]=2;auto moved=db.update_row(tx,"a",first.id,changed);model_a[0]=changed;require(moved.logical_id==first.id.logical_id&&!(moved==first.id),"Cluster key change relocates RID and preserves table LID");require(by_id(db,tx,"b",0).values==other.values,"Other table's same LID remains intact");verify(db,tx);db.commit(tx);
        tx=db.begin();db.savepoint(tx,"before");db.insert_row(tx,"a",json::array({900,1,"new",nullptr}));auto br=by_id(db,tx,"b",1);auto bv=br.values;bv[1]=2;db.update_row(tx,"b",br.id,bv);db.detach_cluster(tx,"a");db.rollback_to(tx,"before");require(db.read_table(tx,"a",false,false).contains("cluster"),"Savepoint restores membership metadata");require(values(db,tx,"a")==model_a&&values(db,tx,"b")==model_b,"Savepoint restores shared pages/FSM/member maps");verify(db,tx);db.commit(tx);
        tx=db.begin();db.set_statistics(tx,"a",json{{"analyzed_rows",12}});auto a_before=db.read_table(tx,"a",false);db.insert_row(tx,"b",json::array({901,0,"new b",nullptr}));model_b[901]=json::array({901,0,"new b",nullptr});auto a_after=db.read_table(tx,"a",false);require(a_after["data_version"]==a_before["data_version"]&&a_after["statistics"]["stale"]==true,"Other member mutation changes shared physical statistics without changing own data version");require(a_after["physical_stats"]["versions"]["cluster_physical_version"]>a_before["physical_stats"]["versions"]["cluster_physical_version"],"Shared physical version invalidates per-table metadata cache");db.commit(tx);
        tx=db.begin();auto target=by_id(db,tx,"a",1);auto baseline=db.diagnostics()["next_page_id"];auto repeated=target.values;for(int i=0;i<500;++i){repeated[2]=i%2?"固定更新乙":"固定更新甲";target.id=db.update_row(tx,"a",target.id,repeated);}model_a[1]=repeated;auto pending=db.transaction_stats(tx);require(pending["private_heap_pages"]==1&&pending["private_index_pages"]==0&&pending["pending_descriptor_count"]==2,"500 member updates keep one final shared HEAP plus two pending descriptors");db.commit(tx);auto committed=db.transaction_stats(tx);require(committed["private_heap_pages"]==1&&committed["private_metadata_pages"]==2&&committed["private_pages"]==3&&committed["wal_bytes"]==104+3*8248,"Exactly shared HEAP+table descriptor+cluster descriptor final WAL images");require(db.diagnostics()["next_page_id"]==baseline,"Repeated same-width clustered updates allocate no pages");
        tx=db.begin();auto expected=by_id(db,tx,"a",1);auto wal=db.diagnostics()["wal_bytes"];for(int i=0;i<500;++i)db.update_row(tx,"a",expected.id,expected.values);require(db.transaction_stats(tx)["dirty_pages"]==0&&db.transaction_stats(tx)["pending_descriptor_count"]==0,"No-op clustered update changes no page or cluster metadata");db.commit(tx);require(db.diagnostics()["wal_bytes"]==wal,"No-op clustered update produces zero WAL");
        tx=db.begin();auto before_pages=db.read_table(tx,"a",false)["physical_stats"]["table_pages"];db.commit(tx);
        TransactionOptions options;options.protocol=TransactionProtocol::Snapshot;options.read_only=true;auto old=db.begin(options);db.refresh_read_view(old,{{"a",true,false},{"b",true,false}});options.read_only=false;auto writer=db.begin(options);db.refresh_read_view(writer,{{"b",false,true}});for(int i=1000;i<1100;++i)db.insert_row(writer,"b",json::array({i,0,"增长",nullptr}));db.commit(writer);
        require(values(db,old,"a")==model_a&&values(db,old,"b")==model_b,"Lazy old snapshot selects consistent cluster descriptor/shared heap/member map after writer");require(db.read_table(old,"a",false)["physical_stats"]["table_pages"]==before_pages,"Old snapshot physical page directory is not latest global state");db.commit(old);for(int i=1000;i<1100;++i)model_b[i]=json::array({i,0,"增长",nullptr});
        tx=db.begin();require(values(db,tx,"b")==model_b,"New view observes committed member growth");verify(db,tx);db.commit(tx);
        tx=db.begin();auto changed_schema=db.read_table(tx,"a",true,false);changed_schema["columns"][2]["name"]="label";changed_schema["columns"].push_back(column("enabled","BOOLEAN"));for(auto& row:changed_schema["rows"])row.push_back(true);db.write_table(tx,"a",changed_schema);for(auto& row:model_a)row.second.push_back(true);require(values(db,tx,"a")==model_a&&values(db,tx,"b")==model_b,"Member binary schema rewrite preserves LIDs/BLOB and leaves other member records intact");require(db.inspect_cluster(tx,"教学聚簇")["total_rows"]==model_a.size()+model_b.size(),"Member rewrite preserves exact shared total row count");verify(db,tx);db.commit(tx);
        tx=db.begin();auto impossible=db.read_table(tx,"a",true,false);impossible["columns"].push_back(column("too_wide","VARCHAR",3000));for(auto& row:impossible["rows"])row.push_back("x");auto allocation=db.diagnostics()["next_page_id"];rejects([&]{db.write_table(tx,"a",impossible);},"ROW_TOO_LARGE");require(db.transaction_stats(tx)["dirty_pages"]==0&&db.diagnostics()["next_page_id"]==allocation,"Invalid member schema rejects before retiring any shared page");db.rollback(tx);
        tx=db.begin();auto bad=definition();bad["columns"][1]=column("dept","VARCHAR",4);bad["rows"]=json::array({json::array({1,"x","bad",nullptr})});db.write_table(tx,"bad",bad);auto wide=definition("FIXED");wide["columns"]=json::array({column("name","VARCHAR",2019)});wide["indexes"]=json::array();db.write_table(tx,"wide",wide);db.create_cluster(tx,"字符串边界");db.commit(tx);
        tx=db.begin();baseline=db.diagnostics()["next_page_id"];rejects([&]{db.attach_cluster(tx,"教学聚簇","bad",{"dept"});},"CLUSTER_KEY");require(db.transaction_stats(tx)["dirty_pages"]==0&&db.diagnostics()["next_page_id"]==baseline,"Incompatible key attach rejects before retire/allocation");db.rollback(tx);
        tx=db.begin();baseline=db.diagnostics()["next_page_id"];rejects([&]{db.attach_cluster(tx,"字符串边界","wide",{"name"});},"ROW_TOO_LARGE");require(db.transaction_stats(tx)["dirty_pages"]==0&&db.diagnostics()["next_page_id"]==baseline,"Fixed row plus OID boundary fails before retire/allocation");db.rollback(tx);
        tx=db.begin();db.detach_cluster(tx,"a");require(!db.read_table(tx,"a",false,false).contains("cluster")&&values(db,tx,"a")==model_a,"Detach preserves every row and BLOB in standalone HEAP");require(values(db,tx,"b")==model_b,"Detach preserves other member data");db.drop_table(tx,"b");require(db.inspect_cluster(tx,"教学聚簇")["members"]==0,"DROP member removes only own rows and membership");db.drop_cluster(tx,"教学聚簇");db.drop_cluster(tx,"字符串边界");require(db.clusters(tx).empty()&&db.catalog(tx).contains("a"),"DROP empty cluster preserves public tables");verify(db,tx);db.commit(tx);db.checkpoint();
    }
    {Storage db(path.u8string(),3);auto tx=db.begin();require(db.clusters(tx).empty()&&values(db,tx,"a")==model_a,"Detached values and deleted cluster reopen after checkpoint");verify(db,tx);db.commit(tx);}
}
void shared_page_conflict(const fs::path& path){Storage db(path.u8string(),3);initialize(db);TransactionOptions options;options.protocol=TransactionProtocol::Snapshot;auto one=db.begin(options),two=db.begin(options);db.refresh_read_view(one,{{"a",false,true}});db.refresh_read_view(two,{{"b",false,true}});auto a=by_id(db,one,"a",0),b=by_id(db,two,"b",0);require(a.id.page_id==b.id.page_id,"Different-table writers really target the same physical shared page");auto av=a.values,bv=b.values;av[2]="snapshot a";bv[2]="snapshot b";db.update_row(one,"a",a.id,av);db.update_row(two,"b",b.id,bv);db.commit(one);rejects([&]{db.commit(two);},"SERIALIZATION_FAILURE");require(db.diagnostics()["recovery_required"]==false,"Pre-WAL baseLSN conflict does not poison storage");auto tx=db.begin();require(by_id(db,tx,"a",0).values==av&&by_id(db,tx,"b",0).values==b.values,"Same-page conflict cannot overwrite first commit or publish loser member");verify(db,tx);db.commit(tx);}
void crash_seed(const std::string& path){Storage db(path,3);auto tx=db.begin();db.create_cluster(tx,"教学聚簇");for(const std::string name:{"a","b"}){auto table=definition();table["rows"]=json::array({json::array({1,0,"base "+name,nullptr})});db.write_table(tx,name,table);db.attach_cluster(tx,"教学聚簇",name,{"dept"});}db.commit(tx);db.checkpoint();}
int crash_child(const std::string& path,const std::string& phase){Storage db(path,3);auto tx=db.begin();db.insert_row(tx,"a",json::array({99,0,"committed a",nullptr}));db.insert_row(tx,"b",json::array({99,0,"committed b",nullptr}));if(phase=="before_commit")std::_Exit(86);
#ifdef _WIN32
    _putenv_s("EDUDB_CRASH_AT",phase.c_str());
#else
    setenv("EDUDB_CRASH_AT",phase.c_str(),1);
#endif
    db.commit(tx);if(phase.rfind("checkpoint_",0)==0)db.checkpoint();return 3;
}
void crash_inspect(const std::string& path){Storage db(path,3);auto tx=db.begin();verify(db,tx);json a=json::array(),b=json::array();for(const auto& row:values(db,tx,"a"))a.push_back(row.second);for(const auto& row:values(db,tx,"b"))b.push_back(row.second);auto shape=db.inspect_cluster(tx,"教学聚簇");db.commit(tx);std::cout<<json{{"status","PASS"},{"a",a},{"b",b},{"total_rows",shape.at("total_rows")},{"recovered_pages",db.diagnostics()["recovered_pages"]},{"wal_generation",db.diagnostics()["wal_generation"]}}.dump()<<"\n";}
}
int main(int argc,char** argv){auto path=fs::temp_directory_path()/("edudb-cluster-kernel-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));try{
    if(argc==3&&std::string(argv[1])=="--prepare-crash"){crash_seed(argv[2]);return 0;}
    if(argc==4&&std::string(argv[1])=="--crash")return crash_child(argv[2],argv[3]);
    if(argc==3&&std::string(argv[1])=="--inspect-crash"){crash_inspect(argv[2]);return 0;}
    fs::create_directory(path);std::ofstream(path/"owned-test.marker")<<"cluster kernel";lifecycle(path/"db");shared_page_conflict(path/"conflict");require(fs::equivalent(path.parent_path(),fs::temp_directory_path())&&path.filename().string().rfind("edudb-cluster-kernel-",0)==0&&fs::exists(path/"owned-test.marker"),"Owned test cleanup");fs::remove_all(path);std::cout<<"PASS cluster Storage kernel "<<checks<<" checks: catalog_v2, shared HEAP, CRUD/index, BLOB, savepoint, page snapshots, shared-page baseLSN conflict, stats, detach/drop/reopen/WAL image count\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL cluster Storage kernel after "<<checks<<" checks: "<<e.what()<<"; evidence at "<<path.u8string()<<"\n";return 1;}}
